-- v2.0 member, researcher and community platform (docs/PLATFORM.md). Generated by scripts/platform-bundle-sql.mjs;
-- do not edit by hand. Apply after release/launch/complete-backend.sql, in the SQL editor or with the platform
-- workflow (.github/workflows/platform.yml). One transaction: on an error nothing is changed. Safe to run again.
begin;

-- SOURCE: migrations/20261026000000_research_data.sql
-- v0.19 research data service and content reports (docs/RESEARCH_DATA.md).
-- Builds on 20261018000000_media_facade_archive.sql (app_admins, archive_role) and Supabase Auth (auth.users).
-- Public project data stays on the static site (GitHub Pages /data/). Only datasets the platform itself curates are
-- member downloads; their files live in the private storage bucket 'research-datasets' and leave it only as signed
-- URLs issued by the research-download Edge Function after it has checked the member.
-- Personal data: only an e-mail address (Supabase Auth) and two consents are required; every other profile field is
-- optional. A deleted account deletes its profile; its download log rows lose the user id (counts stay, no person).

-- ---- member profile (optional fields) --------------------------------------------------------------------------
create table if not exists public.research_profiles(
 user_id uuid primary key references auth.users(id) on delete cascade,
 display_name text check(display_name is null or char_length(display_name) between 1 and 80),
 affiliation text check(affiliation is null or char_length(affiliation) between 1 and 160),
 user_type text check(user_type is null or user_type in ('researcher','student','professional','public','other')),
 research_field text check(research_field is null or char_length(research_field) between 1 and 120),
 purpose text check(purpose is null or char_length(purpose) between 1 and 500),
 country_iso2 text check(country_iso2 is null or country_iso2 ~ '^[A-Z]{2}$'),
 terms_version text not null,
 terms_accepted_at timestamptz not null default now(),
 privacy_version text not null,
 privacy_accepted_at timestamptz not null default now(),
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now()
);
alter table public.research_profiles enable row level security;
revoke all on public.research_profiles from public,anon,authenticated;
grant select,insert,update,delete on public.research_profiles to authenticated;
grant all on public.research_profiles to service_role;
drop policy if exists research_profiles_own on public.research_profiles;
create policy research_profiles_own on public.research_profiles for all to authenticated
 using (user_id=(select auth.uid())) with check (user_id=(select auth.uid()));
create or replace function public.research_profiles_touch() returns trigger language plpgsql set search_path='' as $$
begin new.updated_at:=now(); new.user_id:=old.user_id; new.created_at:=old.created_at; return new; end $$;
drop trigger if exists research_profiles_touch on public.research_profiles;
create trigger research_profiles_touch before update on public.research_profiles for each row execute function public.research_profiles_touch();

-- ---- datasets and versions -------------------------------------------------------------------------------------
-- tier: 'public' (also listed here; files are on the static site), 'member' (signed download after sign-in),
-- 'institution' (by agreement only; never downloadable through the function).
create table if not exists public.research_datasets(
 id text primary key check(id ~ '^[a-z0-9][a-z0-9-]{2,63}$'),
 title_ko text not null,
 title_en text,
 description_ko text,
 tier text not null check(tier in ('public','member','institution')),
 licence text not null,
 licence_url text,
 active boolean not null default true,
 created_at timestamptz not null default now()
);
create table if not exists public.research_dataset_versions(
 dataset_id text not null references public.research_datasets(id) on delete cascade,
 version text not null check(version ~ '^[0-9]+\.[0-9]+\.[0-9]+$'),
 data_as_of date not null,
 created_at timestamptz not null default now(),
 record_count integer not null check(record_count>=0),
 formats text[] not null check(formats <@ array['csv','json','geojson','xlsx']::text[] and cardinality(formats)>0),
 storage_prefix text not null check(storage_prefix ~ '^[a-z0-9][a-z0-9/._-]*$'),
 sha256 jsonb not null default '{}'::jsonb,
 changelog text,
 citation text not null,
 primary key(dataset_id,version)
);
alter table public.research_datasets enable row level security;
alter table public.research_dataset_versions enable row level security;
revoke all on public.research_datasets,public.research_dataset_versions from public,anon,authenticated;
grant select on public.research_datasets,public.research_dataset_versions to anon,authenticated;
grant all on public.research_datasets,public.research_dataset_versions to service_role;
-- The catalogue (titles, versions, licences, citations, checksums) is public; the files are not.
drop policy if exists research_datasets_read on public.research_datasets;
create policy research_datasets_read on public.research_datasets for select to anon,authenticated using (active);
drop policy if exists research_dataset_versions_read on public.research_dataset_versions;
create policy research_dataset_versions_read on public.research_dataset_versions for select to anon,authenticated
 using (exists(select 1 from public.research_datasets d where d.id=dataset_id and d.active));

-- ---- download log (written only by the Edge Function with the service role) ------------------------------------
create table if not exists public.research_downloads(
 id bigint generated always as identity primary key,
 user_id uuid references auth.users(id) on delete set null,
 dataset_id text not null,
 version text not null,
 format text not null,
 ok boolean not null,
 error text check(error is null or char_length(error)<=120),
 requested_at timestamptz not null default now()
);
create index if not exists research_downloads_user on public.research_downloads(user_id,requested_at desc);
create index if not exists research_downloads_dataset on public.research_downloads(dataset_id,requested_at desc);
alter table public.research_downloads enable row level security;
revoke all on public.research_downloads from public,anon,authenticated;
grant select on public.research_downloads to authenticated;
grant all on public.research_downloads to service_role;
drop policy if exists research_downloads_own on public.research_downloads;
create policy research_downloads_own on public.research_downloads for select to authenticated using (user_id=(select auth.uid()));

-- The function's eligibility check, callable only by the service role: member tier, active, version exists,
-- profile with both consents.
create or replace function public.research_download_check(p_user uuid,p_dataset text,p_version text,p_format text)
returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare d public.research_datasets; v public.research_dataset_versions;
begin
 select * into d from public.research_datasets where id=p_dataset;
 if d.id is null or not d.active then return jsonb_build_object('ok',false,'error','dataset_not_found'); end if;
 if d.tier<>'member' then return jsonb_build_object('ok',false,'error',case when d.tier='public' then 'public_dataset_use_site' else 'institution_agreement_required' end); end if;
 select * into v from public.research_dataset_versions where dataset_id=p_dataset and version=p_version;
 if v.dataset_id is null then return jsonb_build_object('ok',false,'error','version_not_found'); end if;
 if not (p_format=any(v.formats)) then return jsonb_build_object('ok',false,'error','format_not_available'); end if;
 if not exists(select 1 from public.research_profiles p where p.user_id=p_user) then return jsonb_build_object('ok',false,'error','profile_and_consent_required'); end if;
 return jsonb_build_object('ok',true,'path',v.storage_prefix||'/'||p_dataset||'-'||p_version||'.'||p_format,
  'licence',d.licence,'licence_url',d.licence_url,'citation',v.citation,'sha256',v.sha256->>p_format,'data_as_of',v.data_as_of,'record_count',v.record_count);
end $$;
revoke all on function public.research_download_check(uuid,text,text,text) from public,anon,authenticated;
grant execute on function public.research_download_check(uuid,text,text,text) to service_role;

-- ---- content reports (image or project errors from visitors) ---------------------------------------------------
-- Anyone may file a report; nobody but admins and editors can read them. A report never changes data by itself.
create table if not exists public.content_reports(
 id bigint generated always as identity primary key,
 created_at timestamptz not null default now(),
 project_id text not null check(project_id ~ '^[A-Za-z0-9_-]{2,40}$'),
 image_id text check(image_id is null or char_length(image_id)<=200),
 reason text not null check(reason in ('image_unrelated','person_image','low_quality','rights_or_credit','project_info','other')),
 message text check(message is null or char_length(message)<=2000),
 contact_email text check(contact_email is null or (char_length(contact_email)<=254 and contact_email ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$')),
 reporter uuid references auth.users(id) on delete set null,
 status text not null default 'open' check(status in ('open','accepted','rejected','duplicate')),
 handled_by uuid references auth.users(id) on delete set null,
 handled_at timestamptz,
 note text check(note is null or char_length(note)<=1000)
);
create index if not exists content_reports_open on public.content_reports(status,created_at desc);
-- A reporter's e-mail address serves only the reply: it is erased when the report is handled (privacy policy §2).
create or replace function public.content_reports_handled() returns trigger language plpgsql set search_path='' as $$
begin if new.status<>'open' then new.contact_email:=null; end if; return new; end $$;
drop trigger if exists content_reports_handled on public.content_reports;
create trigger content_reports_handled before update of status on public.content_reports for each row execute function public.content_reports_handled();
alter table public.content_reports enable row level security;
revoke all on public.content_reports from public,anon,authenticated;
grant insert(project_id,image_id,reason,message,contact_email,reporter) on public.content_reports to anon,authenticated;
grant select,update(status,handled_by,handled_at,note) on public.content_reports to authenticated;
grant all on public.content_reports to service_role;
drop policy if exists content_reports_file on public.content_reports;
create policy content_reports_file on public.content_reports for insert to anon,authenticated
 with check (status='open' and handled_by is null and handled_at is null and note is null
  and (reporter is null or reporter=(select auth.uid())));
drop policy if exists content_reports_review on public.content_reports;
create policy content_reports_review on public.content_reports for select to authenticated using (public.archive_role() in ('admin','editor'));
drop policy if exists content_reports_handle on public.content_reports;
create policy content_reports_handle on public.content_reports for update to authenticated
 using (public.archive_role() in ('admin','editor')) with check (public.archive_role() in ('admin','editor'));

-- ---- admin statistics: aggregates only, no person-level rows ---------------------------------------------------
create or replace function public.research_admin_stats(p_days integer default 30) returns jsonb
language plpgsql stable security definer set search_path=public,pg_temp as $$
declare since timestamptz:=now()-make_interval(days=>greatest(1,least(coalesce(p_days,30),366)));
begin
 perform public.archive_require(array['admin']);
 return jsonb_build_object(
  'days',greatest(1,least(coalesce(p_days,30),366)),
  'members',(select count(*) from public.research_profiles),
  'new_members',(select count(*) from public.research_profiles where created_at>=since),
  'active_downloaders',(select count(distinct user_id) from public.research_downloads where requested_at>=since and ok and user_id is not null),
  'downloads',(select count(*) from public.research_downloads where requested_at>=since and ok),
  'download_errors',(select count(*) from public.research_downloads where requested_at>=since and not ok),
  'by_dataset',coalesce((select jsonb_object_agg(dataset_id,n) from (select dataset_id,count(*) n from public.research_downloads where requested_at>=since and ok group by dataset_id) x),'{}'::jsonb),
  'user_types',coalesce((select jsonb_object_agg(coalesce(user_type,'not_given'),n) from (select user_type,count(*) n from public.research_profiles group by user_type) x),'{}'::jsonb),
  'open_reports',(select count(*) from public.content_reports where status='open'));
end $$;
revoke all on function public.research_admin_stats(integer) from public,anon,authenticated;
grant execute on function public.research_admin_stats(integer) to authenticated,service_role;

-- ---- private bucket for member datasets ------------------------------------------------------------------------
insert into storage.buckets(id,name,public) values('research-datasets','research-datasets',false) on conflict(id) do update set public=false;
-- No storage.objects policy grants anon or authenticated anything on this bucket: only the service role (the Edge
-- Function) reads it, and members receive short-lived signed URLs.

-- SOURCE: migrations/20261112000000_v2_platform.sql
-- v2.0 platform (docs/PLATFORM.md): member accounts, researcher applications and dataset grants, community content
-- (reviews, comments, likes, photos, submissions), flags, appeals, moderation records, image permission requests and
-- an audit log. Builds on 20261018000000_media_facade_archive.sql (app_admins, archive_role) and
-- 20261026000000_research_data.sql (research_datasets, research_profiles, research_download_check).
--
-- Rules this migration enforces in the database, whatever a client sends:
--  * Roles and approvals live only in server-managed tables (app_admins, member_status, researcher_applications'
--    decision columns, research_grants). No user-editable field (profiles, auth user metadata) decides anything.
--  * Staff actions need the admin or editor role AND a multi-factor session (JWT aal2) unless the operator turns
--    require_staff_mfa off in platform_settings.
--  * Every member write starts as draft or pending. Only staff (or the moderation function with the service role)
--    approve, reject or remove. Editing approved content sends it back to pending. Nothing is public before approval.
--  * The public reads approved content through views that never expose user ids.
--  * Research files: a member needs a confirmed e-mail, an active account, an approved researcher application that has
--    not expired, the current research terms, and an unexpired, unrevoked grant for that dataset.
-- PGlite-tested (tests/platform-sql.test.mjs); not yet run on a Supabase project.

-- ---- settings ----------------------------------------------------------------------------------------------------
create table if not exists public.platform_settings(
 key text primary key check(key ~ '^[a-z_]{3,40}$'),
 value jsonb not null,
 updated_at timestamptz not null default now()
);
alter table public.platform_settings enable row level security;
revoke all on public.platform_settings from public,anon,authenticated;
grant all on public.platform_settings to service_role;
insert into public.platform_settings(key,value) values
 ('research_terms_version','"2026-11"'),
 ('require_staff_mfa','true'),
 ('auto_approve_text','false'),
 ('post_hourly_limit','10'),
 ('photo_daily_limit','20'),
 ('submission_daily_limit','10'),
 ('flag_hourly_limit','20'),
 ('max_links','3'),
 ('auto_hide_flags','3')
on conflict(key) do nothing;

create or replace function public.platform_setting(p_key text) returns jsonb language sql stable security definer set search_path=public as $$
 select value from public.platform_settings where key=p_key
$$;
create or replace function public.platform_setting_int(p_key text,p_default integer) returns integer language sql stable security definer set search_path=public as $$
 select coalesce((select (value#>>'{}')::integer from public.platform_settings where key=p_key),p_default)
$$;
-- What the site may read: the current terms version and whether research applications are open.
create or replace function public.platform_public_settings() returns jsonb language sql stable security definer set search_path=public as $$
 select jsonb_build_object('research_terms_version',public.platform_setting('research_terms_version'))
$$;

-- ---- staff and member checks -------------------------------------------------------------------------------------
-- Staff = admin or editor in app_admins, with an aal2 (MFA) session unless require_staff_mfa is false.
create or replace function public.platform_staff_role() returns text language sql stable security definer set search_path=public as $$
 select a.role from public.app_admins a
 where a.user_id=(select auth.uid()) and a.role in ('admin','editor')
  and (coalesce((select (value#>>'{}')::boolean from public.platform_settings where key='require_staff_mfa'),true)=false
       or coalesce((select auth.jwt())->>'aal','')='aal2')
$$;
create or replace function public.platform_is_staff() returns boolean language sql stable security definer set search_path=public as $$
 select public.platform_staff_role() is not null
$$;
create or replace function public.platform_require(p_roles text[]) returns text language plpgsql stable security definer set search_path=public,pg_temp as $$
declare r text:=public.platform_staff_role();
begin
 if r is null or not r=any(p_roles) then
  if exists(select 1 from public.app_admins a where a.user_id=(select auth.uid()) and a.role=any(p_roles)) then
   raise exception 'mfa_required' using errcode='insufficient_privilege';
  end if;
  raise exception 'staff role required: %',array_to_string(p_roles,' or ') using errcode='insufficient_privilege';
 end if;
 return r;
end $$;

-- Server-managed account state. No grant to members: they read their own through my_account().
create table if not exists public.member_status(
 user_id uuid primary key references auth.users(id) on delete cascade,
 state text not null default 'active' check(state in ('active','suspended','banned')),
 reason text check(reason is null or char_length(reason)<=500),
 until timestamptz,
 updated_by uuid references auth.users(id) on delete set null,
 updated_at timestamptz not null default now()
);
alter table public.member_status enable row level security;
revoke all on public.member_status from public,anon,authenticated;
grant all on public.member_status to service_role;

-- A member may write when the e-mail is confirmed and the account is not suspended or banned.
create or replace function public.platform_member_ok(p_uid uuid) returns boolean language sql stable security definer set search_path=public as $$
 select p_uid is not null
  and exists(select 1 from auth.users u where u.id=p_uid and u.email_confirmed_at is not null)
  and not exists(select 1 from public.member_status s where s.user_id=p_uid and s.state in ('suspended','banned') and (s.until is null or s.until>now()))
$$;

-- Public profile: only a display name and a short bio, both optional and both shown with approved content.
create table if not exists public.member_profiles(
 user_id uuid primary key references auth.users(id) on delete cascade,
 display_name text check(display_name is null or char_length(btrim(display_name)) between 2 and 40),
 bio text check(bio is null or char_length(bio)<=300),
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now()
);
alter table public.member_profiles enable row level security;
revoke all on public.member_profiles from public,anon,authenticated;
grant select,insert,update,delete on public.member_profiles to authenticated;
grant all on public.member_profiles to service_role;
drop policy if exists member_profiles_own on public.member_profiles;
create policy member_profiles_own on public.member_profiles for all to authenticated
 using (user_id=(select auth.uid())) with check (user_id=(select auth.uid()));
-- Visibility helpers for policies and triggers that run in the member's session (where RLS hides other members' rows).
create or replace function public.platform_account_restricted(p_uid uuid) returns boolean language sql stable security definer set search_path=public as $$
 select exists(select 1 from public.member_status s where s.user_id=p_uid and s.state<>'active' and (s.until is null or s.until>now()))
$$;
create or replace function public.platform_display_name(p_uid uuid) returns text language sql stable security definer set search_path=public as $$
 select coalesce(nullif(btrim((select display_name from public.member_profiles where user_id=p_uid)),''),'이용자')
$$;

-- ---- audit log (written only by the security definer functions below) -------------------------------------------
create table if not exists public.platform_audit_log(
 id bigint generated always as identity primary key,
 at timestamptz not null default now(),
 actor uuid references auth.users(id) on delete set null,
 action text not null check(char_length(action)<=60),
 target_type text not null check(char_length(target_type)<=40),
 target_id text,
 detail jsonb not null default '{}'::jsonb
);
create index if not exists platform_audit_log_at on public.platform_audit_log(at desc);
alter table public.platform_audit_log enable row level security;
revoke all on public.platform_audit_log from public,anon,authenticated;
grant all on public.platform_audit_log to service_role;
create or replace function public.platform_audit(p_action text,p_type text,p_id text,p_detail jsonb default '{}'::jsonb) returns void
language sql security definer set search_path=public as $$
 insert into public.platform_audit_log(actor,action,target_type,target_id,detail) values((select auth.uid()),p_action,p_type,p_id,coalesce(p_detail,'{}'::jsonb))
$$;
revoke all on function public.platform_audit(text,text,text,jsonb) from public,anon,authenticated;

-- ---- researcher applications and dataset grants -------------------------------------------------------------------
-- Alternative verification instead of ID documents: an institutional page, ORCID, a publication, or a supervisor's
-- contact for students. No document upload in v2.0 (docs/PLATFORM.md "Researcher verification").
alter table public.research_datasets drop constraint if exists research_datasets_tier_check;
alter table public.research_datasets add constraint research_datasets_tier_check check(tier in ('public','member','researcher','institution'));

create table if not exists public.researcher_applications(
 id bigint generated always as identity primary key,
 user_id uuid not null references auth.users(id) on delete cascade,
 full_name text not null check(char_length(btrim(full_name)) between 2 and 80),
 affiliation text check(affiliation is null or char_length(affiliation) between 2 and 160),
 applicant_type text not null check(applicant_type in ('faculty','researcher','graduate_student','undergraduate','independent','professional','other')),
 research_field text not null check(char_length(btrim(research_field)) between 2 and 120),
 purpose text not null check(char_length(btrim(purpose)) between 20 and 2000),
 requested_datasets text[] not null default '{}' check(cardinality(requested_datasets) between 1 and 10),
 verification_url text check(verification_url is null or (verification_url ~ '^https://' and char_length(verification_url)<=500)),
 verification_note text check(verification_note is null or char_length(verification_note)<=500),
 terms_version text not null,
 terms_accepted_at timestamptz not null default now(),
 privacy_version text not null,
 status text not null default 'submitted' check(status in ('submitted','in_review','needs_info','approved','rejected','revoked','expired','withdrawn')),
 decision_reason text check(decision_reason is null or char_length(decision_reason)<=1000),
 decided_by uuid references auth.users(id) on delete set null,
 decided_at timestamptz,
 expires_at timestamptz,
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now()
);
create unique index if not exists researcher_applications_one_open on public.researcher_applications(user_id) where status in ('submitted','in_review','needs_info','approved');
create index if not exists researcher_applications_queue on public.researcher_applications(status,created_at);
alter table public.researcher_applications enable row level security;
revoke all on public.researcher_applications from public,anon,authenticated;
grant select,delete on public.researcher_applications to authenticated;
grant insert(full_name,affiliation,applicant_type,research_field,purpose,requested_datasets,verification_url,verification_note,terms_version,privacy_version) on public.researcher_applications to authenticated;
grant update(affiliation,research_field,purpose,requested_datasets,verification_url,verification_note,terms_version,status) on public.researcher_applications to authenticated;
grant all on public.researcher_applications to service_role;
drop policy if exists researcher_applications_own_read on public.researcher_applications;
create policy researcher_applications_own_read on public.researcher_applications for select to authenticated using (user_id=(select auth.uid()));
drop policy if exists researcher_applications_own_insert on public.researcher_applications;
create policy researcher_applications_own_insert on public.researcher_applications for insert to authenticated
 with check (user_id=(select auth.uid()) and status='submitted' and public.platform_member_ok((select auth.uid())));
-- A member edits only an application that asks for more information (it goes back to submitted) or withdraws one.
drop policy if exists researcher_applications_own_update on public.researcher_applications;
create policy researcher_applications_own_update on public.researcher_applications for update to authenticated
 using (user_id=(select auth.uid()) and status in ('submitted','needs_info','approved'))
 with check (user_id=(select auth.uid()) and status in ('submitted','withdrawn','approved'));
drop policy if exists researcher_applications_own_delete on public.researcher_applications;
create policy researcher_applications_own_delete on public.researcher_applications for delete to authenticated
 using (user_id=(select auth.uid()) and status in ('submitted','withdrawn','rejected','expired','revoked'));

create or replace function public.researcher_applications_guard() returns trigger language plpgsql set search_path=public,pg_temp as $$
declare privileged boolean:=current_user not in ('anon','authenticated');
begin
 if tg_op='INSERT' then
  if not privileged then new.user_id:=(select auth.uid()); new.status:='submitted'; new.decision_reason:=null; new.decided_by:=null; new.decided_at:=null; new.expires_at:=null; end if;
  if not (new.requested_datasets <@ coalesce((select array_agg(id) from public.research_datasets where active and tier in ('member','researcher')),'{}')) then
   raise exception 'unknown_dataset' using errcode='check_violation';
  end if;
  return new;
 end if;
 new.updated_at:=now();
 if not privileged then
  new.user_id:=old.user_id; new.full_name:=old.full_name; new.applicant_type:=old.applicant_type; new.privacy_version:=old.privacy_version;
  new.decision_reason:=old.decision_reason; new.decided_by:=old.decided_by; new.decided_at:=old.decided_at; new.expires_at:=old.expires_at; new.created_at:=old.created_at;
  if old.status='approved' then
   -- An approved researcher may only accept newer terms; nothing else changes.
   if new.status<>'approved' or (to_jsonb(new)-'terms_version'-'terms_accepted_at'-'updated_at')<>(to_jsonb(old)-'terms_version'-'terms_accepted_at'-'updated_at') then
    raise exception 'approved_application_locked' using errcode='insufficient_privilege';
   end if;
   new.terms_accepted_at:=now();
  elsif new.status='withdrawn' then null;
  else new.status:='submitted';
  end if;
 end if;
 return new;
end $$;
drop trigger if exists researcher_applications_guard on public.researcher_applications;
create trigger researcher_applications_guard before insert or update on public.researcher_applications for each row execute function public.researcher_applications_guard();

create table if not exists public.research_grants(
 id bigint generated always as identity primary key,
 user_id uuid not null references auth.users(id) on delete cascade,
 dataset_id text not null references public.research_datasets(id) on delete cascade,
 application_id bigint references public.researcher_applications(id) on delete set null,
 granted_by uuid references auth.users(id) on delete set null,
 granted_at timestamptz not null default now(),
 expires_at timestamptz not null,
 revoked_at timestamptz,
 revoked_by uuid references auth.users(id) on delete set null,
 revoke_reason text check(revoke_reason is null or char_length(revoke_reason)<=500)
);
create unique index if not exists research_grants_one_active on public.research_grants(user_id,dataset_id) where revoked_at is null;
alter table public.research_grants enable row level security;
revoke all on public.research_grants from public,anon,authenticated;
grant select on public.research_grants to authenticated;
grant all on public.research_grants to service_role;
drop policy if exists research_grants_own on public.research_grants;
create policy research_grants_own on public.research_grants for select to authenticated using (user_id=(select auth.uid()));

-- Admin decisions on an application. approve: creates (or renews) one grant per requested dataset, valid until
-- p_expires (at most two years). needs_info / reject / revoke record the reason; revoke also revokes every grant.
create or replace function public.research_application_decide(p_id bigint,p_decision text,p_reason text default null,p_expires timestamptz default null,p_datasets text[] default null)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare a public.researcher_applications; ds text; exp timestamptz; n integer:=0;
begin
 perform public.platform_require(array['admin']);
 select * into a from public.researcher_applications where id=p_id for update;
 if a.id is null then raise exception 'application_not_found'; end if;
 if p_decision not in ('in_review','needs_info','approved','rejected','revoked') then raise exception 'invalid_decision'; end if;
 if p_decision in ('needs_info','rejected','revoked') and coalesce(btrim(p_reason),'')='' then raise exception 'reason_required'; end if;
 if p_decision='approved' then
  if a.status not in ('submitted','in_review','needs_info') then raise exception 'not_reviewable'; end if;
  exp:=least(coalesce(p_expires,now()+interval '1 year'),now()+interval '2 years');
  if exp<=now() then raise exception 'invalid_expiry'; end if;
  for ds in select unnest(coalesce(p_datasets,a.requested_datasets)) loop
   if not exists(select 1 from public.research_datasets where id=ds and active and tier in ('member','researcher')) then raise exception 'unknown_dataset: %',ds; end if;
   update public.research_grants set revoked_at=now(),revoked_by=(select auth.uid()),revoke_reason='renewed' where user_id=a.user_id and dataset_id=ds and revoked_at is null;
   insert into public.research_grants(user_id,dataset_id,application_id,granted_by,expires_at) values(a.user_id,ds,a.id,(select auth.uid()),exp);
   n:=n+1;
  end loop;
  update public.researcher_applications set status='approved',decision_reason=p_reason,decided_by=(select auth.uid()),decided_at=now(),expires_at=exp where id=p_id;
 elsif p_decision='revoked' then
  update public.research_grants set revoked_at=now(),revoked_by=(select auth.uid()),revoke_reason=p_reason where user_id=a.user_id and revoked_at is null;
  get diagnostics n=row_count;
  update public.researcher_applications set status='revoked',decision_reason=p_reason,decided_by=(select auth.uid()),decided_at=now() where id=p_id;
 else
  if a.status not in ('submitted','in_review','needs_info') then raise exception 'not_reviewable'; end if;
  update public.researcher_applications set status=p_decision,decision_reason=p_reason,decided_by=(select auth.uid()),decided_at=now() where id=p_id;
 end if;
 perform public.platform_audit('research_application_'||p_decision,'researcher_application',p_id::text,jsonb_build_object('grants',n,'reason',p_reason));
 return jsonb_build_object('ok',true,'status',p_decision,'grants',n);
end $$;
create or replace function public.research_grant_revoke(p_grant bigint,p_reason text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
begin
 perform public.platform_require(array['admin']);
 if coalesce(btrim(p_reason),'')='' then raise exception 'reason_required'; end if;
 update public.research_grants set revoked_at=now(),revoked_by=(select auth.uid()),revoke_reason=p_reason where id=p_grant and revoked_at is null;
 if not found then raise exception 'grant_not_found_or_revoked'; end if;
 perform public.platform_audit('research_grant_revoked','research_grant',p_grant::text,jsonb_build_object('reason',p_reason));
 return jsonb_build_object('ok',true);
end $$;
-- Expiry: approved applications past expires_at become expired (the download check uses the timestamps anyway).
create or replace function public.platform_expire() returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare n integer;
begin
 update public.researcher_applications set status='expired',updated_at=now() where status='approved' and expires_at is not null and expires_at<=now();
 get diagnostics n=row_count;
 return jsonb_build_object('expired_applications',n);
end $$;

-- The download check of the research-download Edge Function (service role only). v2.0: 'member' and 'researcher'
-- datasets both need an approved researcher with a grant; signing in is not enough.
create or replace function public.research_download_check(p_user uuid,p_dataset text,p_version text,p_format text)
returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare d public.research_datasets; v public.research_dataset_versions; a public.researcher_applications; g public.research_grants; terms text:=public.platform_setting('research_terms_version')#>>'{}';
begin
 select * into d from public.research_datasets where id=p_dataset;
 if d.id is null or not d.active then return jsonb_build_object('ok',false,'error','dataset_not_found'); end if;
 if d.tier not in ('member','researcher') then return jsonb_build_object('ok',false,'error',case when d.tier='public' then 'public_dataset_use_site' else 'institution_agreement_required' end); end if;
 select * into v from public.research_dataset_versions where dataset_id=p_dataset and version=p_version;
 if v.dataset_id is null then return jsonb_build_object('ok',false,'error','version_not_found'); end if;
 if not (p_format=any(v.formats)) then return jsonb_build_object('ok',false,'error','format_not_available'); end if;
 if not public.platform_member_ok(p_user) then return jsonb_build_object('ok',false,'error','account_restricted'); end if;
 select * into a from public.researcher_applications where user_id=p_user and status='approved' order by decided_at desc limit 1;
 if a.id is null then return jsonb_build_object('ok',false,'error','researcher_approval_required'); end if;
 if a.expires_at is not null and a.expires_at<=now() then return jsonb_build_object('ok',false,'error','access_expired'); end if;
 if terms is not null and a.terms_version<>terms then return jsonb_build_object('ok',false,'error','terms_update_required','terms_version',terms); end if;
 select * into g from public.research_grants where user_id=p_user and dataset_id=p_dataset and revoked_at is null order by granted_at desc limit 1;
 if g.id is null then return jsonb_build_object('ok',false,'error','dataset_not_granted'); end if;
 if g.expires_at<=now() then return jsonb_build_object('ok',false,'error','access_expired'); end if;
 return jsonb_build_object('ok',true,'path',v.storage_prefix||'/'||p_dataset||'-'||p_version||'.'||p_format,
  'licence',d.licence,'licence_url',d.licence_url,'citation',v.citation,'sha256',v.sha256->>p_format,'data_as_of',v.data_as_of,'record_count',v.record_count,'grant_expires_at',g.expires_at);
end $$;
revoke all on function public.research_download_check(uuid,text,text,text) from public,anon,authenticated;
grant execute on function public.research_download_check(uuid,text,text,text) to service_role;

-- ---- community content --------------------------------------------------------------------------------------------
-- Statuses (all content tables): draft (saved, private), pending (waiting for moderation), needs_review (moderation
-- unsure, or flagged: a person decides), approved (public), rejected (not published, reason given), removed (taken
-- down after publication).
create table if not exists public.community_posts(
 id bigint generated always as identity primary key,
 user_id uuid not null references auth.users(id) on delete cascade,
 kind text not null check(kind in ('review','question','info')),
 project_id text check(project_id is null or project_id ~ '^[A-Za-z0-9_-]{2,40}$'),
 title text not null check(char_length(btrim(title)) between 2 and 120),
 body text not null check(char_length(btrim(body)) between 10 and 5000),
 visited_on date check(visited_on is null or visited_on<=current_date),
 author_name text,
 status text not null default 'pending' check(status in ('draft','pending','needs_review','approved','rejected','removed')),
 moderation jsonb,
 decision_reason text check(decision_reason is null or char_length(decision_reason)<=1000),
 decided_by uuid references auth.users(id) on delete set null,
 decided_at timestamptz,
 published_at timestamptz,
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now(),
 constraint community_posts_review_project check(kind<>'review' or project_id is not null)
);
create index if not exists community_posts_public on public.community_posts(project_id,published_at desc) where status='approved';
create index if not exists community_posts_queue on public.community_posts(status,created_at) where status in ('pending','needs_review');

-- Whether a post is public, for policies and triggers in a member's session (RLS hides other members' rows there).
create or replace function public.platform_post_is_public(p_id bigint) returns boolean language sql stable security definer set search_path=public as $$
 select exists(select 1 from public.community_posts p where p.id=p_id and p.status='approved')
$$;

create table if not exists public.community_comments(
 id bigint generated always as identity primary key,
 user_id uuid not null references auth.users(id) on delete cascade,
 post_id bigint not null references public.community_posts(id) on delete cascade,
 body text not null check(char_length(btrim(body)) between 2 and 2000),
 author_name text,
 status text not null default 'pending' check(status in ('draft','pending','needs_review','approved','rejected','removed')),
 moderation jsonb,
 decision_reason text check(decision_reason is null or char_length(decision_reason)<=1000),
 decided_by uuid references auth.users(id) on delete set null,
 decided_at timestamptz,
 published_at timestamptz,
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now()
);
create index if not exists community_comments_post on public.community_comments(post_id,created_at) where status='approved';

create table if not exists public.community_likes(
 post_id bigint not null references public.community_posts(id) on delete cascade,
 user_id uuid not null references auth.users(id) on delete cascade,
 created_at timestamptz not null default now(),
 primary key(post_id,user_id)
);

-- Member photos. The file is uploaded to the private bucket community-uploads (<uid>/<name>) and, once a person
-- approved it, copied re-encoded to the public bucket community-photos by the publish-photo function (public_path).
-- Gallery approval and adoption as an official image are separate decisions (official_review).
create table if not exists public.community_photos(
 id bigint generated always as identity primary key,
 user_id uuid not null references auth.users(id) on delete cascade,
 project_id text not null check(project_id ~ '^[A-Za-z0-9_-]{2,40}$'),
 upload_path text not null check(upload_path ~ '^[0-9a-f-]{36}/[A-Za-z0-9._-]{1,80}\.(jpg|jpeg|png|webp)$'),
 public_path text check(public_path is null or public_path ~ '^[A-Za-z0-9/._-]{1,200}$'),
 caption text check(caption is null or char_length(caption)<=300),
 taken_on date check(taken_on is null or taken_on<=current_date),
 mime text not null check(mime in ('image/jpeg','image/png','image/webp')),
 bytes integer not null check(bytes between 1 and 8388608),
 width integer not null check(width between 600 and 12000),
 height integer not null check(height between 400 and 12000),
 -- The member's own statements, all required: own photo, may grant the licence, no identifiable person without
 -- consent, and the notice that the artwork shown may have its own rights (not cleared by this statement).
 own_photo boolean not null check(own_photo),
 can_license boolean not null check(can_license),
 people_ok boolean not null check(people_ok),
 artwork_rights_notice boolean not null check(artwork_rights_notice),
 licence text not null default 'display' check(licence in ('display','cc-by-4.0','cc-by-sa-4.0')),
 offer_official boolean not null default false,
 official_review text check(official_review is null or official_review in ('pending','accepted','declined')),
 author_name text,
 status text not null default 'pending' check(status in ('draft','pending','needs_review','approved','rejected','removed')),
 moderation jsonb,
 decision_reason text check(decision_reason is null or char_length(decision_reason)<=1000),
 decided_by uuid references auth.users(id) on delete set null,
 decided_at timestamptz,
 published_at timestamptz,
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now(),
 constraint community_photos_own_folder check(split_part(upload_path,'/',1)=user_id::text)
);
create index if not exists community_photos_public on public.community_photos(project_id,published_at desc) where status='approved';

-- Submissions: a tip (name and a link), a new project application, a creator's own work, a correction to an existing
-- project, or an event. Drafts may be incomplete; submitting (pending) requires the fields of its kind.
create table if not exists public.community_submissions(
 id bigint generated always as identity primary key,
 user_id uuid not null references auth.users(id) on delete cascade,
 kind text not null check(kind in ('tip','new_project','creator_work','correction','event')),
 project_id text check(project_id is null or project_id ~ '^[A-Za-z0-9_-]{2,40}$'),
 name text check(name is null or char_length(btrim(name)) between 2 and 200),
 name_en text check(name_en is null or char_length(name_en)<=200),
 country_iso2 text check(country_iso2 is null or country_iso2 ~ '^[A-Z]{2}$'),
 city text check(city is null or char_length(city)<=120),
 venue text check(venue is null or char_length(venue)<=200),
 project_type text check(project_type is null or project_type in ('media_facade','media_architecture','projection_mapping','light_art','media_wall','urban_screen','interactive_installation','festival_program','other')),
 creators text check(creators is null or char_length(creators)<=500),
 year_start integer check(year_start is null or year_start between 1850 and 2100),
 description text check(description is null or char_length(description)<=5000),
 official_url text check(official_url is null or (official_url ~ '^https?://' and char_length(official_url)<=500)),
 source_urls text[] not null default '{}' check(cardinality(source_urls)<=10),
 field_name text check(field_name is null or char_length(field_name)<=60),
 proposed_value text check(proposed_value is null or char_length(proposed_value)<=2000),
 event_starts_on date,
 event_ends_on date,
 image_note text check(image_note is null or char_length(image_note)<=1000),
 relation text check(relation is null or relation in ('visitor','artist','producer','organizer','researcher','other')),
 author_name text,
 checks jsonb,
 approved_project_id text check(approved_project_id is null or approved_project_id ~ '^[A-Za-z0-9_-]{2,40}$'),
 status text not null default 'draft' check(status in ('draft','pending','needs_review','approved','rejected','removed')),
 moderation jsonb,
 decision_reason text check(decision_reason is null or char_length(decision_reason)<=1000),
 decided_by uuid references auth.users(id) on delete set null,
 decided_at timestamptz,
 published_at timestamptz,
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now(),
 constraint community_submissions_event_dates check(event_ends_on is null or event_starts_on is null or event_ends_on>=event_starts_on)
);
create index if not exists community_submissions_queue on public.community_submissions(status,created_at) where status in ('pending','needs_review');

-- What a submitted (pending) item of each kind must carry. Pure: also used by the client.
create or replace function public.community_submission_missing(s public.community_submissions) returns text[] language sql immutable set search_path='' as $$
 select array_remove(array[
  case when s.kind in ('tip','new_project','creator_work','event') and s.name is null then 'name' end,
  case when s.kind in ('new_project','creator_work') and s.country_iso2 is null then 'country_iso2' end,
  case when s.kind in ('new_project','creator_work') and s.city is null and s.venue is null then 'city_or_venue' end,
  case when s.kind in ('new_project','creator_work') and s.project_type is null then 'project_type' end,
  case when s.kind in ('new_project','creator_work') and coalesce(char_length(s.description),0)<30 then 'description' end,
  case when s.kind in ('new_project','creator_work','event') and s.official_url is null and cardinality(s.source_urls)=0 then 'source' end,
  case when s.kind='tip' and s.official_url is null and cardinality(s.source_urls)=0 and coalesce(char_length(s.description),0)<10 then 'source_or_description' end,
  case when s.kind='correction' and (s.project_id is null or s.field_name is null or s.proposed_value is null) then 'correction_fields' end,
  case when s.kind='correction' and s.official_url is null and cardinality(s.source_urls)=0 then 'source' end,
  case when s.kind='event' and s.event_starts_on is null then 'event_starts_on' end
 ],null)
$$;

-- ---- server-side rule checks (the moderation function adds contextual checks) ------------------------------------
-- Hard rules reject the write; soft rules send it to a person (needs_review) with the reason in moderation.rules.
create or replace function public.platform_text_rules(p_text text) returns jsonb language plpgsql immutable set search_path='' as $$
declare links integer; t text:=coalesce(p_text,''); flags text[]:='{}';
begin
 links:=(select count(*) from regexp_matches(t,'(https?://|www\.)[^[:space:]<>"'']+','gi'));
 if t ~* '(javascript|data|vbscript):' then return jsonb_build_object('block','unsafe_scheme'); end if;
 if t ~ '[0-9]{6}[- ]?[1-4][0-9]{6}' then flags:=array_append(flags,'privacy:resident_number'); end if;
 if t ~ '01[016789][- .]?[0-9]{3,4}[- .]?[0-9]{4}' then flags:=array_append(flags,'privacy:phone'); end if;
 if t ~* '[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}' then flags:=array_append(flags,'privacy:email'); end if;
 if t ~* '(bit\.ly|tinyurl\.com|goo\.gl|t\.co|is\.gd|cutt\.ly|han\.gl|me2\.do)/' then flags:=array_append(flags,'link:shortener'); end if;
 if t ~* 'https?://[0-9]{1,3}(\.[0-9]{1,3}){3}' then flags:=array_append(flags,'link:ip_host'); end if;
 if t ~ '(.)\1{19,}' then flags:=array_append(flags,'spam:repetition'); end if;
 return jsonb_build_object('links',links,'flags',to_jsonb(flags));
end $$;

-- The guard of every community content table. Members: owner forced, status only draft or pending, moderation and
-- decision fields untouchable, rate limits, rule checks, edits of approved content go back to pending, removed
-- content is locked. Staff and the service role pass (their changes go through platform_moderate).
create or replace function public.community_guard() returns trigger language plpgsql set search_path=public,pg_temp as $$
declare privileged boolean:=current_user not in ('anon','authenticated'); uid uuid:=(select auth.uid()); r jsonb; txt text; lim integer; n integer;
 meta text[]:=array['status','moderation','decision_reason','decided_by','decided_at','published_at','updated_at','checks','approved_project_id','official_review','public_path','author_name'];
begin
 if privileged then
  if tg_op='UPDATE' then new.updated_at:=now(); end if;
  return new;
 end if;
 if tg_op='INSERT' then
  if uid is null or not public.platform_member_ok(uid) then raise exception 'account_restricted' using errcode='insufficient_privilege'; end if;
  new.user_id:=uid;
  if new.status not in ('draft','pending') then new.status:='pending'; end if;
  new.moderation:=null; new.decision_reason:=null; new.decided_by:=null; new.decided_at:=null; new.published_at:=null;
  new.author_name:=public.platform_display_name(uid);
  if tg_table_name='community_photos' then new.public_path:=null; new.official_review:=case when new.offer_official then 'pending' end; end if;
  if tg_table_name='community_submissions' then new.checks:=null; new.approved_project_id:=null; end if;
  -- Rate limits over the member's own rows (visible to them through RLS).
  if tg_table_name in ('community_posts','community_comments') then
   lim:=public.platform_setting_int('post_hourly_limit',10);
   execute format('select count(*) from public.%I where user_id=$1 and created_at>now()-interval ''1 hour''',tg_table_name) into n using uid;
  elsif tg_table_name='community_photos' then
   lim:=public.platform_setting_int('photo_daily_limit',20);
   select count(*) into n from public.community_photos where user_id=uid and created_at>now()-interval '1 day';
  else
   lim:=public.platform_setting_int('submission_daily_limit',10);
   select count(*) into n from public.community_submissions where user_id=uid and created_at>now()-interval '1 day';
  end if;
  if n>=lim then raise exception 'rate_limited' using errcode='check_violation'; end if;
 else
  if old.status='removed' then raise exception 'content_removed_locked' using errcode='insufficient_privilege'; end if;
  new.user_id:=old.user_id; new.created_at:=old.created_at; new.updated_at:=now();
  new.moderation:=old.moderation; new.decision_reason:=old.decision_reason; new.decided_by:=old.decided_by; new.decided_at:=old.decided_at; new.author_name:=old.author_name;
  if tg_table_name='community_photos' then
   new.public_path:=old.public_path; new.upload_path:=old.upload_path; new.mime:=old.mime; new.bytes:=old.bytes; new.width:=old.width; new.height:=old.height;
   new.official_review:=case when new.offer_official and old.official_review is null then 'pending' when not new.offer_official then null else old.official_review end;
  end if;
  if tg_table_name='community_submissions' then new.checks:=old.checks; new.approved_project_id:=old.approved_project_id; end if;
  if new.status not in ('draft','pending') then
   -- Unchanged status (approved, needs_review, rejected) is kept only if the content did not change.
   if new.status=old.status and (to_jsonb(new)-meta)=(to_jsonb(old)-meta) then return new; end if;
   if new.status<>old.status then raise exception 'status_not_allowed' using errcode='insufficient_privilege'; end if;
   new.status:='pending';
  end if;
  if old.status not in ('draft') and new.status='draft' then new.status:='pending'; end if;
  new.published_at:=case when new.status='approved' then old.published_at end;
 end if;
 -- Rule checks on what the member wrote.
 -- Read through jsonb: one function serves tables with different columns.
 txt:=(select concat_ws(' ',j->>'title',j->>'body',j->>'caption',j->>'name',j->>'description',j->>'creators',j->>'proposed_value',j->>'image_note') from (select to_jsonb(new) j) x);
 r:=public.platform_text_rules(txt);
 if r ? 'block' then raise exception 'content_blocked: %',r->>'block' using errcode='check_violation'; end if;
 if (r->>'links')::integer>public.platform_setting_int('max_links',3) then raise exception 'too_many_links' using errcode='check_violation'; end if;
 -- Table-specific checks sit in their own IF: PL/pgSQL plans an expression with this table's row type.
 if tg_table_name='community_submissions' then
  if new.status='pending' and cardinality(public.community_submission_missing(new))>0 then
   raise exception 'missing_fields: %',array_to_string(public.community_submission_missing(new),',') using errcode='check_violation';
  end if;
 end if;
 if tg_table_name='community_comments' then
  if not public.platform_post_is_public(new.post_id) then raise exception 'post_not_public' using errcode='check_violation'; end if;
 end if;
 if new.status='pending' and jsonb_array_length(r->'flags')>0 then
  new.status:='needs_review';
  new.moderation:=jsonb_build_object('source','rules','flags',r->'flags','at',now());
 end if;
 return new;
end $$;

do $$ declare t text; begin
 foreach t in array array['community_posts','community_comments','community_photos','community_submissions'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('revoke all on public.%I from public,anon,authenticated',t);
  execute format('grant select,insert,update,delete on public.%I to authenticated',t);
  execute format('grant all on public.%I to service_role',t);
  execute format('drop policy if exists %I on public.%I',t||'_own',t);
  execute format('create policy %I on public.%I for all to authenticated using (user_id=(select auth.uid())) with check (user_id=(select auth.uid()))',t||'_own',t);
  execute format('drop policy if exists %I on public.%I',t||'_staff_read',t);
  execute format('create policy %I on public.%I for select to authenticated using (public.platform_is_staff())',t||'_staff_read',t);
  execute format('drop trigger if exists %I on public.%I',t||'_guard',t);
  execute format('create trigger %I before insert or update on public.%I for each row execute function public.community_guard()',t||'_guard',t);
 end loop;
end $$;
-- Members never set user_id, moderation or decision columns: community_guard resets them on every write.

alter table public.community_likes enable row level security;
revoke all on public.community_likes from public,anon,authenticated;
grant select,insert,delete on public.community_likes to authenticated;
grant all on public.community_likes to service_role;
drop policy if exists community_likes_own on public.community_likes;
create policy community_likes_own on public.community_likes for all to authenticated
 using (user_id=(select auth.uid()))
 with check (user_id=(select auth.uid()) and public.platform_member_ok((select auth.uid()))
  and public.platform_post_is_public(post_id));

-- Public views: approved content only, no user ids. They run with the owner's rights on purpose (security_barrier);
-- the WHERE clauses are the access rule.
-- Dropped first: a later migration (20261113010000_v2_admin_members.sql) adds a column, and a re-run must not fail.
drop view if exists public.community_public_posts;
create view public.community_public_posts with (security_barrier) as
 select p.id,p.kind,p.project_id,p.author_name,p.title,p.body,p.visited_on,p.published_at,
  (select count(*) from public.community_likes l where l.post_id=p.id) as like_count,
  (select count(*) from public.community_comments c where c.post_id=p.id and c.status='approved') as comment_count
 from public.community_posts p where p.status='approved';
create or replace view public.community_public_comments with (security_barrier) as
 select c.id,c.post_id,c.author_name,c.body,c.published_at from public.community_comments c
 where c.status='approved' and exists(select 1 from public.community_posts p where p.id=c.post_id and p.status='approved');
-- Dropped first: a later migration (20261113000000_v2_photo_grades.sql) adds columns, and a re-run must not fail.
drop view if exists public.community_public_photos;
create view public.community_public_photos with (security_barrier) as
 select f.id,f.project_id,f.author_name,f.caption,f.taken_on,f.public_path,f.width,f.height,f.licence,f.published_at
 from public.community_photos f where f.status='approved' and f.public_path is not null;
revoke all on public.community_public_posts,public.community_public_comments,public.community_public_photos from public,anon,authenticated;
grant select on public.community_public_posts,public.community_public_comments,public.community_public_photos to anon,authenticated,service_role;

-- ---- flags (reports on community content) and appeals --------------------------------------------------------------
create table if not exists public.content_flags(
 id bigint generated always as identity primary key,
 created_at timestamptz not null default now(),
 target_type text not null check(target_type in ('post','comment','photo','submission','profile')),
 target_id bigint not null,
 reason text not null check(reason in ('sexual','child_safety','violence','hate','harassment','privacy','spam','malicious_link','copyright','unrelated','false_info','other')),
 message text check(message is null or char_length(message)<=2000),
 contact_email text check(contact_email is null or (char_length(contact_email)<=254 and contact_email ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$')),
 reporter uuid references auth.users(id) on delete set null,
 status text not null default 'open' check(status in ('open','actioned','dismissed')),
 handled_by uuid references auth.users(id) on delete set null,
 handled_at timestamptz,
 note text check(note is null or char_length(note)<=1000)
);
-- v2.0 drafts had a check here; the rule for non-members lives in content_flags_before (deleted members' flags keep no reporter).
alter table public.content_flags drop constraint if exists content_flags_anon;
create index if not exists content_flags_open on public.content_flags(status,created_at desc);
create index if not exists content_flags_target on public.content_flags(target_type,target_id);
alter table public.content_flags enable row level security;
revoke all on public.content_flags from public,anon,authenticated;
grant insert(target_type,target_id,reason,message,contact_email,reporter) on public.content_flags to anon,authenticated;
grant select on public.content_flags to authenticated;
grant all on public.content_flags to service_role;
drop policy if exists content_flags_file on public.content_flags;
create policy content_flags_file on public.content_flags for insert to anon,authenticated
 with check (status='open' and handled_by is null and (reporter is null or reporter=(select auth.uid())));
drop policy if exists content_flags_staff on public.content_flags;
create policy content_flags_staff on public.content_flags for select to authenticated using (public.platform_is_staff());

-- Rate limit, and auto-hide: a child-safety flag, or auto_hide_flags open flags from different members, moves an
-- approved item to needs_review (hidden) until a person decides. The reply address is erased once the flag is handled.
create or replace function public.content_flags_after() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
declare tbl text:=case new.target_type when 'post' then 'community_posts' when 'comment' then 'community_comments' when 'photo' then 'community_photos' when 'submission' then 'community_submissions' end; n integer;
begin
 if tbl is null then return new; end if;
 select count(distinct coalesce(reporter::text,contact_email)) into n from public.content_flags where target_type=new.target_type and target_id=new.target_id and status='open';
 if new.reason='child_safety' or n>=public.platform_setting_int('auto_hide_flags',3) then
  execute format('update public.%I set status=''needs_review'',moderation=coalesce(moderation,''{}''::jsonb)||jsonb_build_object(''hidden_by_flags'',$2,''at'',now()) where id=$1 and status=''approved''',tbl) using new.target_id,n;
 end if;
 return new;
end $$;
-- Runs in the caller's session (current_user tells anon from members); the count needs the definer helper.
create or replace function public.platform_flag_recent(p_uid uuid) returns integer language sql stable security definer set search_path=public as $$
 select count(*)::integer from public.content_flags where reporter=p_uid and created_at>now()-interval '1 hour'
$$;
create or replace function public.content_flags_before() returns trigger language plpgsql set search_path=public,pg_temp as $$
declare n integer;
begin
 if tg_op='UPDATE' then if new.status<>'open' then new.contact_email:=null; end if; return new; end if;
 -- Members report as themselves; non-members may file only copyright notices, with an address for the reply.
 if current_user='authenticated' then new.reporter:=(select auth.uid()); end if;
 if current_user='anon' then
  new.reporter:=null;
  if new.reason<>'copyright' or new.contact_email is null then raise exception 'sign_in_required_or_copyright_notice' using errcode='insufficient_privilege'; end if;
 end if;
 if new.reporter is not null then
  n:=public.platform_flag_recent(new.reporter);
  if n>=public.platform_setting_int('flag_hourly_limit',20) then raise exception 'rate_limited' using errcode='check_violation'; end if;
 end if;
 return new;
end $$;
drop trigger if exists content_flags_before on public.content_flags;
create trigger content_flags_before before insert or update on public.content_flags for each row execute function public.content_flags_before();
drop trigger if exists content_flags_after on public.content_flags;
create trigger content_flags_after after insert on public.content_flags for each row execute function public.content_flags_after();

create table if not exists public.moderation_appeals(
 id bigint generated always as identity primary key,
 user_id uuid not null references auth.users(id) on delete cascade,
 target_type text not null check(target_type in ('post','comment','photo','submission','account')),
 target_id bigint,
 message text not null check(char_length(btrim(message)) between 10 and 2000),
 status text not null default 'open' check(status in ('open','upheld','reversed')),
 decided_by uuid references auth.users(id) on delete set null,
 decided_at timestamptz,
 note text check(note is null or char_length(note)<=1000),
 created_at timestamptz not null default now()
);
create unique index if not exists moderation_appeals_one_open on public.moderation_appeals(user_id,target_type,coalesce(target_id,0)) where status='open';
alter table public.moderation_appeals enable row level security;
revoke all on public.moderation_appeals from public,anon,authenticated;
grant select on public.moderation_appeals to authenticated;
grant insert(target_type,target_id,message) on public.moderation_appeals to authenticated;
grant all on public.moderation_appeals to service_role;
drop policy if exists moderation_appeals_own on public.moderation_appeals;
create policy moderation_appeals_own on public.moderation_appeals for select to authenticated using (user_id=(select auth.uid()) or public.platform_is_staff());
drop policy if exists moderation_appeals_file on public.moderation_appeals;
-- An appeal is about the member's own rejected or removed content, or their own account restriction.
create policy moderation_appeals_file on public.moderation_appeals for insert to authenticated
 with check (user_id=(select auth.uid()) and status='open' and (
  (target_type='account' and public.platform_account_restricted((select auth.uid())))
  or (target_type='post' and exists(select 1 from public.community_posts x where x.id=target_id and x.user_id=(select auth.uid()) and x.status in ('rejected','removed')))
  or (target_type='comment' and exists(select 1 from public.community_comments x where x.id=target_id and x.user_id=(select auth.uid()) and x.status in ('rejected','removed')))
  or (target_type='photo' and exists(select 1 from public.community_photos x where x.id=target_id and x.user_id=(select auth.uid()) and x.status in ('rejected','removed')))
  or (target_type='submission' and exists(select 1 from public.community_submissions x where x.id=target_id and x.user_id=(select auth.uid()) and x.status in ('rejected','removed')))));
create or replace function public.moderation_appeals_owner() returns trigger language plpgsql set search_path=public,pg_temp as $$
begin if current_user in ('anon','authenticated') then new.user_id:=(select auth.uid()); new.status:='open'; new.decided_by:=null; new.decided_at:=null; new.note:=null; end if; return new; end $$;
drop trigger if exists moderation_appeals_owner on public.moderation_appeals;
create trigger moderation_appeals_owner before insert on public.moderation_appeals for each row execute function public.moderation_appeals_owner();

-- ---- moderation records and decisions ------------------------------------------------------------------------------
create table if not exists public.moderation_events(
 id bigint generated always as identity primary key,
 at timestamptz not null default now(),
 target_type text not null,
 target_id bigint not null,
 source text not null check(source in ('rules','auto','staff','flags','appeal')),
 decision text not null check(decision in ('approved','needs_review','rejected','removed','restored')),
 categories jsonb not null default '{}'::jsonb,
 model text,
 actor uuid references auth.users(id) on delete set null,
 reason text
);
create index if not exists moderation_events_target on public.moderation_events(target_type,target_id,at desc);
alter table public.moderation_events enable row level security;
revoke all on public.moderation_events from public,anon,authenticated;
grant all on public.moderation_events to service_role;

create or replace function public.platform_table_of(p_type text) returns text language sql immutable set search_path='' as $$
 select case p_type when 'post' then 'community_posts' when 'comment' then 'community_comments' when 'photo' then 'community_photos' when 'submission' then 'community_submissions' end
$$;

-- Staff decision on one item (admin or editor, MFA). approved publishes (published_at), removed takes down, needs_review
-- hides; rejected and removed need a reason the member sees.
create or replace function public.platform_moderate(p_type text,p_id bigint,p_decision text,p_reason text default null,p_project text default null)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare tbl text:=public.platform_table_of(p_type); cur text;
begin
 perform public.platform_require(array['admin','editor']);
 if tbl is null then raise exception 'invalid_target'; end if;
 if p_decision not in ('approved','needs_review','rejected','removed') then raise exception 'invalid_decision'; end if;
 if p_decision in ('rejected','removed') and coalesce(btrim(p_reason),'')='' then raise exception 'reason_required'; end if;
 execute format('select status from public.%I where id=$1 for update',tbl) into cur using p_id;
 if cur is null then raise exception 'not_found'; end if;
 if cur='draft' then raise exception 'draft_not_submitted'; end if;
 if p_type='photo' and p_decision='approved' and not exists(select 1 from public.community_photos where id=p_id and public_path is not null) then
  raise exception 'photo_not_published_use_publish_photo';
 end if;
 if p_type='submission' and p_decision='approved' and p_project is null and exists(select 1 from public.community_submissions where id=p_id and kind in ('new_project','creator_work')) then
  raise exception 'project_id_required';
 end if;
 execute format('update public.%I set status=$2,decision_reason=$3,decided_by=$4,decided_at=now(),published_at=case when $2=''approved'' then coalesce(published_at,now()) else published_at end where id=$1',tbl)
  using p_id,p_decision,p_reason,(select auth.uid());
 if p_type='submission' and p_project is not null then update public.community_submissions set approved_project_id=p_project where id=p_id; end if;
 insert into public.moderation_events(target_type,target_id,source,decision,actor,reason) values(p_type,p_id,'staff',p_decision,(select auth.uid()),p_reason);
 perform public.platform_audit('moderate_'||p_decision,p_type,p_id::text,jsonb_build_object('reason',p_reason,'from',cur,'project',p_project));
 return jsonb_build_object('ok',true,'status',p_decision);
end $$;

-- The moderation function (service role only): records the automatic result; approves only when auto_approve_text
-- is on and the item is text. Photos always wait for a person.
create or replace function public.platform_moderation_apply(p_type text,p_id bigint,p_decision text,p_categories jsonb,p_model text)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare tbl text:=public.platform_table_of(p_type); cur text; final text:=p_decision;
begin
 if tbl is null then raise exception 'invalid_target'; end if;
 if p_decision not in ('approved','needs_review','rejected') then raise exception 'invalid_decision'; end if;
 execute format('select status from public.%I where id=$1 for update',tbl) into cur using p_id;
 if cur is distinct from 'pending' then return jsonb_build_object('ok',false,'error','not_pending','status',cur); end if;
 if final='approved' and (p_type in ('photo','submission') or coalesce((public.platform_setting('auto_approve_text')#>>'{}')::boolean,false)=false) then final:='needs_review'; end if;
 execute format('update public.%I set status=$2,moderation=$3,published_at=case when $2=''approved'' then now() end,decision_reason=case when $2=''rejected'' then ''자동 검수: 운영정책 위반 가능성'' end where id=$1',tbl)
  using p_id,final,jsonb_build_object('source','auto','model',p_model,'categories',coalesce(p_categories,'{}'::jsonb),'suggested',p_decision,'at',now());
 insert into public.moderation_events(target_type,target_id,source,decision,categories,model) values(p_type,p_id,'auto',final,coalesce(p_categories,'{}'::jsonb),p_model);
 return jsonb_build_object('ok',true,'status',final);
end $$;
create or replace function public.platform_moderation_pending(p_limit integer default 50) returns table(target_type text,target_id bigint,text_content text,created_at timestamptz)
language sql stable security definer set search_path=public as $$
 select * from (
  select 'post'::text,id,concat_ws(E'\n',title,body),created_at from public.community_posts where status='pending'
  union all select 'comment',id,body,created_at from public.community_comments where status='pending'
  union all select 'photo',id,coalesce(caption,''),created_at from public.community_photos where status='pending'
  union all select 'submission',id,concat_ws(E'\n',name,description,creators,proposed_value,image_note,array_to_string(source_urls,' '),official_url),created_at from public.community_submissions where status='pending'
 ) x order by 4 limit greatest(1,least(coalesce(p_limit,50),200))
$$;
-- Set by the publish-photo function after it copied the re-encoded file to the public bucket.
create or replace function public.platform_photo_published(p_id bigint,p_public_path text,p_actor uuid) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
begin
 if not exists(select 1 from public.app_admins a where a.user_id=p_actor and a.role in ('admin','editor')) then raise exception 'staff role required'; end if;
 update public.community_photos set public_path=p_public_path,status='approved',published_at=coalesce(published_at,now()),decided_by=p_actor,decided_at=now() where id=p_id and status in ('pending','needs_review');
 if not found then raise exception 'not_reviewable'; end if;
 insert into public.moderation_events(target_type,target_id,source,decision,actor) values('photo',p_id,'staff','approved',p_actor);
 insert into public.platform_audit_log(actor,action,target_type,target_id,detail) values(p_actor,'photo_published','photo',p_id::text,jsonb_build_object('path',p_public_path));
 return jsonb_build_object('ok',true);
end $$;
-- Adoption of a member photo as an official image candidate: a separate decision after gallery approval.
create or replace function public.platform_photo_official(p_id bigint,p_decision text,p_reason text default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
begin
 perform public.platform_require(array['admin','editor']);
 if p_decision not in ('accepted','declined') then raise exception 'invalid_decision'; end if;
 update public.community_photos set official_review=p_decision where id=p_id and status='approved' and offer_official and licence in ('cc-by-4.0','cc-by-sa-4.0');
 if not found then raise exception 'not_eligible: needs an approved photo offered under a CC licence'; end if;
 perform public.platform_audit('photo_official_'||p_decision,'photo',p_id::text,jsonb_build_object('reason',p_reason));
 return jsonb_build_object('ok',true);
end $$;

create or replace function public.flag_handle(p_id bigint,p_action text,p_note text default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
begin
 perform public.platform_require(array['admin','editor']);
 if p_action not in ('actioned','dismissed') then raise exception 'invalid_action'; end if;
 update public.content_flags set status=p_action,handled_by=(select auth.uid()),handled_at=now(),note=p_note where id=p_id and status='open';
 if not found then raise exception 'flag_not_open'; end if;
 perform public.platform_audit('flag_'||p_action,'content_flag',p_id::text,jsonb_build_object('note',p_note));
 return jsonb_build_object('ok',true);
end $$;
create or replace function public.appeal_decide(p_id bigint,p_decision text,p_note text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare a public.moderation_appeals; tbl text;
begin
 perform public.platform_require(array['admin','editor']);
 if p_decision not in ('upheld','reversed') then raise exception 'invalid_decision'; end if;
 if coalesce(btrim(p_note),'')='' then raise exception 'note_required'; end if;
 select * into a from public.moderation_appeals where id=p_id and status='open' for update;
 if a.id is null then raise exception 'appeal_not_open'; end if;
 update public.moderation_appeals set status=p_decision,decided_by=(select auth.uid()),decided_at=now(),note=p_note where id=p_id;
 if p_decision='reversed' then
  if a.target_type='account' then
   update public.member_status set state='active',reason=null,until=null,updated_by=(select auth.uid()),updated_at=now() where user_id=a.user_id;
  else
   tbl:=public.platform_table_of(a.target_type);
   execute format('update public.%I set status=''needs_review'' where id=$1',tbl) using a.target_id;
   insert into public.moderation_events(target_type,target_id,source,decision,actor,reason) values(a.target_type,a.target_id,'appeal','restored',(select auth.uid()),p_note);
  end if;
 end if;
 perform public.platform_audit('appeal_'||p_decision,'appeal',p_id::text,jsonb_build_object('note',p_note));
 return jsonb_build_object('ok',true);
end $$;

-- Accounts and roles (admin only). The last admin cannot be removed.
create or replace function public.platform_set_member_status(p_user uuid,p_state text,p_reason text,p_until timestamptz default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
begin
 perform public.platform_require(array['admin']);
 if p_state not in ('active','suspended','banned') then raise exception 'invalid_state'; end if;
 if p_state<>'active' and coalesce(btrim(p_reason),'')='' then raise exception 'reason_required'; end if;
 if p_user=(select auth.uid()) then raise exception 'cannot_restrict_self'; end if;
 insert into public.member_status(user_id,state,reason,until,updated_by,updated_at) values(p_user,p_state,p_reason,p_until,(select auth.uid()),now())
 on conflict(user_id) do update set state=excluded.state,reason=excluded.reason,until=excluded.until,updated_by=excluded.updated_by,updated_at=now();
 perform public.platform_audit('member_'||p_state,'member',p_user::text,jsonb_build_object('reason',p_reason,'until',p_until));
 return jsonb_build_object('ok',true);
end $$;
create or replace function public.platform_set_role(p_user uuid,p_role text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
begin
 perform public.platform_require(array['admin']);
 if p_role is not null and p_role not in ('admin','editor') then raise exception 'invalid_role'; end if;
 if (p_role is null or p_role<>'admin') and exists(select 1 from public.app_admins where user_id=p_user and role='admin')
    and (select count(*) from public.app_admins where role='admin')<=1 then raise exception 'last_admin'; end if;
 if p_role is null then delete from public.app_admins where user_id=p_user;
 else insert into public.app_admins(user_id,role) values(p_user,p_role) on conflict(user_id) do update set role=excluded.role; end if;
 perform public.platform_audit('role_'||coalesce(p_role,'removed'),'member',p_user::text,'{}'::jsonb);
 return jsonb_build_object('ok',true);
end $$;

-- What a member sees about their own account (no other person's data).
create or replace function public.my_account() returns jsonb language sql stable security definer set search_path=public as $$
 select case when (select auth.uid()) is null then null else jsonb_build_object(
  'user_id',(select auth.uid()),
  'email_confirmed',exists(select 1 from auth.users u where u.id=(select auth.uid()) and u.email_confirmed_at is not null),
  'state',coalesce((select jsonb_build_object('state',s.state,'reason',s.reason,'until',s.until) from public.member_status s where s.user_id=(select auth.uid())),jsonb_build_object('state','active')),
  'staff_role',(select a.role from public.app_admins a where a.user_id=(select auth.uid()) and a.role in ('admin','editor')),
  'staff_mfa_ok',public.platform_is_staff(),
  'research_terms_version',public.platform_setting('research_terms_version'),
  'application',(select jsonb_build_object('id',a.id,'status',a.status,'decision_reason',a.decision_reason,'expires_at',a.expires_at,'terms_version',a.terms_version,'requested_datasets',a.requested_datasets,'created_at',a.created_at)
    from public.researcher_applications a where a.user_id=(select auth.uid()) order by a.created_at desc limit 1),
  'grants',coalesce((select jsonb_agg(jsonb_build_object('dataset_id',g.dataset_id,'expires_at',g.expires_at,'revoked',g.revoked_at is not null) order by g.granted_at desc)
    from public.research_grants g where g.user_id=(select auth.uid())),'[]'::jsonb)) end
$$;

-- Staff queue and statistics (aggregates; the queue lists items, not members).
create or replace function public.platform_admin_queue(p_type text,p_status text default 'needs_review',p_limit integer default 50) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare tbl text:=public.platform_table_of(p_type); out jsonb;
begin
 perform public.platform_require(array['admin','editor']);
 if p_type='application' then
  perform public.platform_require(array['admin']);
  select coalesce(jsonb_agg(to_jsonb(a) order by a.created_at),'[]'::jsonb) into out from (select a.*,u.email from public.researcher_applications a join auth.users u on u.id=a.user_id where a.status=p_status order by a.created_at limit greatest(1,least(p_limit,200))) a;
  return out;
 elsif p_type='flag' then
  select coalesce(jsonb_agg(to_jsonb(f) order by f.created_at),'[]'::jsonb) into out from (select * from public.content_flags where status=coalesce(nullif(p_status,'needs_review'),'open') order by created_at limit greatest(1,least(p_limit,200))) f;
  return out;
 elsif p_type='appeal' then
  select coalesce(jsonb_agg(to_jsonb(f) order by f.created_at),'[]'::jsonb) into out from (select * from public.moderation_appeals where status='open' order by created_at limit greatest(1,least(p_limit,200))) f;
  return out;
 elsif tbl is null then raise exception 'invalid_target';
 end if;
 execute format('select coalesce(jsonb_agg(to_jsonb(x)-''user_id'' order by x.created_at),''[]''::jsonb) from (select * from public.%I where status=$1 order by created_at limit $2) x',tbl) into out using p_status,greatest(1,least(p_limit,200));
 return out;
end $$;
create or replace function public.platform_admin_stats() returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
begin
 perform public.platform_require(array['admin','editor']);
 return jsonb_build_object(
  'members',(select count(*) from auth.users),
  'restricted',(select count(*) from public.member_status where state<>'active' and (until is null or until>now())),
  'applications',coalesce((select jsonb_object_agg(status,n) from (select status,count(*) n from public.researcher_applications group by status) x),'{}'::jsonb),
  'active_grants',(select count(*) from public.research_grants where revoked_at is null and expires_at>now()),
  'queue',jsonb_build_object(
   'posts',(select count(*) from public.community_posts where status in ('pending','needs_review')),
   'comments',(select count(*) from public.community_comments where status in ('pending','needs_review')),
   'photos',(select count(*) from public.community_photos where status in ('pending','needs_review')),
   'submissions',(select count(*) from public.community_submissions where status in ('pending','needs_review')),
   'flags',(select count(*) from public.content_flags where status='open'),
   'appeals',(select count(*) from public.moderation_appeals where status='open')),
  'published',jsonb_build_object(
   'posts',(select count(*) from public.community_posts where status='approved'),
   'photos',(select count(*) from public.community_photos where status='approved'),
   'submissions',(select count(*) from public.community_submissions where status='approved')));
end $$;
create or replace function public.platform_audit_recent(p_limit integer default 100) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare out jsonb;
begin
 perform public.platform_require(array['admin']);
 select coalesce(jsonb_agg(to_jsonb(l) order by l.at desc),'[]'::jsonb) into out from (select * from public.platform_audit_log order by at desc limit greatest(1,least(p_limit,500))) l;
 return out;
end $$;

-- ---- image permission requests (staff only) -----------------------------------------------------------------------
-- A rights holder's contact details are kept only here (never in the public repository or the static site).
create table if not exists public.image_permission_requests(
 id bigint generated always as identity primary key,
 project_id text not null check(project_id ~ '^[A-Za-z0-9_-]{2,40}$'),
 image_ref text not null check(char_length(image_ref) between 3 and 1000),
 rights_holder text not null check(char_length(rights_holder) between 2 and 200),
 contact_channel text not null check(contact_channel in ('email','web_form','post','phone','other')),
 contact_value text check(contact_value is null or char_length(contact_value)<=500),
 purpose text not null default '빛의 건축 아카이브의 작품 상세 페이지 대표 이미지(저작자 표시)' check(char_length(purpose)<=1000),
 requested_scope text not null default 'display_with_credit' check(requested_scope in ('display_with_credit','display_and_thumbnail','cc_by','cc_by_sa','other')),
 granted_scope text check(granted_scope is null or char_length(granted_scope)<=500),
 status text not null default 'draft' check(status in ('draft','sent','replied','approved','denied','withdrawn','expired','revoked')),
 requested_at timestamptz,
 response_at timestamptz,
 evidence_note text check(evidence_note is null or char_length(evidence_note)<=2000),
 valid_until date,
 revoked_at timestamptz,
 created_by uuid references auth.users(id) on delete set null,
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now()
);
create index if not exists image_permission_requests_project on public.image_permission_requests(project_id);
alter table public.image_permission_requests enable row level security;
revoke all on public.image_permission_requests from public,anon,authenticated;
grant select,insert,update,delete on public.image_permission_requests to authenticated;
grant all on public.image_permission_requests to service_role;
drop policy if exists image_permission_requests_staff on public.image_permission_requests;
create policy image_permission_requests_staff on public.image_permission_requests for all to authenticated
 using (public.platform_is_staff()) with check (public.platform_is_staff());
create or replace function public.image_permission_touch() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
begin
 new.updated_at:=now();
 if tg_op='INSERT' then new.created_by:=coalesce((select auth.uid()),new.created_by); end if;
 if new.status='sent' and new.requested_at is null then new.requested_at:=now(); end if;
 if new.status in ('replied','approved','denied') and new.response_at is null then new.response_at:=now(); end if;
 if new.status='revoked' and new.revoked_at is null then new.revoked_at:=now(); end if;
 if tg_op='UPDATE' and old.status is distinct from new.status then
  insert into public.platform_audit_log(actor,action,target_type,target_id,detail) values((select auth.uid()),'permission_'||new.status,'image_permission_request',new.id::text,jsonb_build_object('from',old.status));
 end if;
 return new;
end $$;
drop trigger if exists image_permission_touch on public.image_permission_requests;
create trigger image_permission_touch before insert or update on public.image_permission_requests for each row execute function public.image_permission_touch();

-- ---- storage --------------------------------------------------------------------------------------------------------
-- community-uploads: private; a member writes and reads only their own folder; staff read for review. 8 MB, images only.
-- community-photos: public read; written only by the publish-photo function (service role).
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values
 ('community-uploads','community-uploads',false,8388608,array['image/jpeg','image/png','image/webp']),
 ('community-photos','community-photos',true,8388608,array['image/jpeg','image/webp'])
on conflict(id) do update set public=excluded.public,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
drop policy if exists community_uploads_own_insert on storage.objects;
create policy community_uploads_own_insert on storage.objects for insert to authenticated
 with check (bucket_id='community-uploads' and (storage.foldername(name))[1]=(select auth.uid())::text
  and storage.extension(name) in ('jpg','jpeg','png','webp') and public.platform_member_ok((select auth.uid())));
drop policy if exists community_uploads_own_read on storage.objects;
create policy community_uploads_own_read on storage.objects for select to authenticated
 using (bucket_id='community-uploads' and ((storage.foldername(name))[1]=(select auth.uid())::text or public.platform_is_staff()));
drop policy if exists community_uploads_own_delete on storage.objects;
create policy community_uploads_own_delete on storage.objects for delete to authenticated
 using (bucket_id='community-uploads' and (storage.foldername(name))[1]=(select auth.uid())::text);

-- ---- function privileges ----------------------------------------------------------------------------------------------
do $$ declare f text; begin
 foreach f in array array[
  'public.platform_setting(text)','public.platform_setting_int(text,integer)','public.platform_member_ok(uuid)','public.platform_display_name(uuid)',
  'public.platform_post_is_public(bigint)','public.platform_account_restricted(uuid)','public.platform_flag_recent(uuid)',
  'public.platform_staff_role()','public.platform_is_staff()','public.platform_require(text[])','public.platform_public_settings()','public.my_account()',
  'public.research_application_decide(bigint,text,text,timestamptz,text[])','public.research_grant_revoke(bigint,text)','public.platform_expire()',
  'public.platform_moderate(text,bigint,text,text,text)','public.platform_moderation_apply(text,bigint,text,jsonb,text)','public.platform_moderation_pending(integer)',
  'public.platform_photo_published(bigint,text,uuid)','public.platform_photo_official(bigint,text,text)','public.flag_handle(bigint,text,text)','public.appeal_decide(bigint,text,text)',
  'public.platform_set_member_status(uuid,text,text,timestamptz)','public.platform_set_role(uuid,text)','public.platform_admin_queue(text,text,integer)',
  'public.platform_admin_stats()','public.platform_audit_recent(integer)','public.community_submission_missing(public.community_submissions)','public.platform_text_rules(text)','public.platform_table_of(text)'] loop
  execute format('revoke all on function %s from public,anon,authenticated',f);
 end loop;
end $$;
-- Helpers that RLS policies and triggers call in the member's session.
grant execute on function public.platform_flag_recent(uuid),public.platform_setting_int(text,integer) to anon;
grant execute on function public.platform_member_ok(uuid),public.platform_display_name(uuid),public.platform_post_is_public(bigint),public.platform_account_restricted(uuid),public.platform_flag_recent(uuid),public.platform_is_staff(),public.platform_staff_role(),
 public.platform_setting_int(text,integer),public.platform_text_rules(text),public.community_submission_missing(public.community_submissions),public.platform_table_of(text) to authenticated;
grant execute on function public.platform_public_settings() to anon,authenticated;
grant execute on function public.my_account(),public.platform_require(text[]),public.research_application_decide(bigint,text,text,timestamptz,text[]),public.research_grant_revoke(bigint,text),
 public.platform_moderate(text,bigint,text,text,text),public.platform_photo_official(bigint,text,text),public.flag_handle(bigint,text,text),public.appeal_decide(bigint,text,text),
 public.platform_set_member_status(uuid,text,text,timestamptz),public.platform_set_role(uuid,text),public.platform_admin_queue(text,text,integer),public.platform_admin_stats(),
 public.platform_audit_recent(integer) to authenticated;
grant execute on function public.platform_moderation_apply(text,bigint,text,jsonb,text),public.platform_moderation_pending(integer),public.platform_photo_published(bigint,text,uuid),
 public.platform_expire(),public.platform_setting(text) to service_role;
grant execute on all functions in schema public to service_role;

-- SOURCE: migrations/20261113000000_v2_photo_grades.sql
-- v2.0 image brief (docs/IMAGE_GRADES.md, docs/PLATFORM.md "Photos"): member photos get the photographer's credit
-- line, the grade a staff member gives when publishing (A premium, B general, C context), and the published file's
-- SHA-256, so the same file is never published twice. Members may set the credit line only; the grade and the hash are
-- written by platform_photo_published (staff, through the publish-photo function).

alter table public.community_photos add column if not exists credit_name text
 check(credit_name is null or (char_length(credit_name) between 1 and 80 and credit_name !~* '(https?://|www\.|@)'));
alter table public.community_photos add column if not exists grade text check(grade is null or grade in ('A','B','C'));
alter table public.community_photos add column if not exists sha256 text check(sha256 is null or sha256 ~ '^[0-9a-f]{64}$');
create unique index if not exists community_photos_sha256_once on public.community_photos(sha256) where sha256 is not null and status='approved';

-- Members never write the grade or the hash (the same rule as community_guard: privileged = not anon/authenticated).
create or replace function public.community_photos_staff_fields() returns trigger language plpgsql set search_path=public,pg_temp as $$
begin
 if current_user not in ('anon','authenticated') then return new; end if;
 if tg_op='INSERT' then new.grade:=null; new.sha256:=null;
 else new.grade:=old.grade; new.sha256:=old.sha256; end if;
 return new;
end $$;
drop trigger if exists community_photos_staff_fields on public.community_photos;
create trigger community_photos_staff_fields before insert or update on public.community_photos for each row execute function public.community_photos_staff_fields();

-- Publication now records the staff grade and the file hash; a file already published (same SHA-256) is refused.
drop function if exists public.platform_photo_published(bigint,text,uuid);
create or replace function public.platform_photo_published(p_id bigint,p_public_path text,p_actor uuid,p_grade text,p_sha256 text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
begin
 if not exists(select 1 from public.app_admins a where a.user_id=p_actor and a.role in ('admin','editor')) then raise exception 'staff role required'; end if;
 if p_grade is null or p_grade not in ('A','B','C') then raise exception 'grade_required'; end if;
 if p_sha256 is null or p_sha256 !~ '^[0-9a-f]{64}$' then raise exception 'hash_required'; end if;
 if exists(select 1 from public.community_photos where sha256=p_sha256 and status='approved' and id<>p_id) then raise exception 'duplicate_photo'; end if;
 update public.community_photos set public_path=p_public_path,status='approved',grade=p_grade,sha256=p_sha256,published_at=coalesce(published_at,now()),decided_by=p_actor,decided_at=now() where id=p_id and status in ('pending','needs_review');
 if not found then raise exception 'not_reviewable'; end if;
 insert into public.moderation_events(target_type,target_id,source,decision,actor) values('photo',p_id,'staff','approved',p_actor);
 insert into public.platform_audit_log(actor,action,target_type,target_id,detail) values(p_actor,'photo_published','photo',p_id::text,jsonb_build_object('path',p_public_path,'grade',p_grade));
 return jsonb_build_object('ok',true,'grade',p_grade);
end $$;
revoke all on function public.platform_photo_published(bigint,text,uuid,text,text) from public,anon,authenticated;
grant execute on function public.platform_photo_published(bigint,text,uuid,text,text) to service_role;

-- The public view adds the credit line (the member's own, else their display name) and the grade; same rows and the
-- same grants as before, still no user id. Grade C photos are shown as the visitor's view of the place, never as the
-- work's photo.
drop view if exists public.community_public_photos;
create view public.community_public_photos with (security_barrier) as
 select f.id,f.project_id,f.author_name,f.caption,f.taken_on,f.public_path,f.width,f.height,f.licence,f.published_at,
  coalesce(f.credit_name,f.author_name) as credit,f.grade
 from public.community_photos f where f.status='approved' and f.public_path is not null;
revoke all on public.community_public_photos from public,anon,authenticated;
grant select on public.community_public_photos to anon,authenticated,service_role;

-- SOURCE: migrations/20261113010000_v2_admin_members.sql
-- v2.0 P0 (docs/PLATFORM.md): what the operator console still lacked, and public member profiles.
--  - platform_member_list: members with their account state, role and activity (admin only, with an MFA session;
--    every call is written to the audit log because it shows e-mail addresses);
--  - platform_research_grants and platform_research_downloads: research access and its log (admin only);
--  - member profiles get a random public id (never the account id) and an opt-out, so a member's public posts can be
--    listed under their profile; profile text is checked like posts (no links, contacts or staff-like names).
-- Re-runnable after 20261112000000_v2_platform.sql and 20261113000000_v2_photo_grades.sql.

-- ---- public profile ---------------------------------------------------------------------------------------------------
alter table public.member_profiles add column if not exists public_id uuid not null default gen_random_uuid();
alter table public.member_profiles add column if not exists show_profile boolean not null default true;
create unique index if not exists member_profiles_public_id on public.member_profiles(public_id);

-- Members choose their name, bio and whether the profile is shown; the public id is the server's. Text rules: no
-- links, e-mail addresses or phone numbers in the name, nothing that reads as staff, and the post rules for the bio.
create or replace function public.member_profiles_guard() returns trigger language plpgsql set search_path=public,pg_temp as $$
declare r jsonb; flags jsonb;
begin
 if current_user not in ('anon','authenticated') then return new; end if;
 if tg_op='INSERT' then new.public_id:=gen_random_uuid(); else new.public_id:=old.public_id; new.created_at:=old.created_at; end if;
 new.updated_at:=now();
 if new.display_name is not null then
  new.display_name:=btrim(regexp_replace(new.display_name,'[[:space:]]+',' ','g'));
  if new.display_name ~* '(https?://|www\.|[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}|[0-9]{2,4}[-. ]?[0-9]{3,4}[-. ]?[0-9]{4})' then raise exception 'profile_name_contact' using errcode='check_violation'; end if;
  if lower(new.display_name) ~ '(운영자|관리자|운영진|빛의 ?건축|admin|moderator|official|staff)' then raise exception 'profile_name_reserved' using errcode='check_violation'; end if;
 end if;
 if new.bio is not null then
  r:=public.platform_text_rules(new.bio); flags:=coalesce(r->'flags','[]'::jsonb);
  if (r->>'links')::int>1 or flags ?| array['link:shortener','link:ip_host','spam:repetition','privacy:phone','privacy:email','privacy:resident_number'] then raise exception 'profile_bio_rules' using errcode='check_violation'; end if;
 end if;
 return new;
end $$;
drop trigger if exists member_profiles_guard on public.member_profiles;
create trigger member_profiles_guard before insert or update on public.member_profiles for each row execute function public.member_profiles_guard();

-- The public posts view carries the author's public id when the profile is shown (null otherwise); a profile view lists
-- shown profiles of members in good standing with their number of public posts. Neither carries an account id.
drop view if exists public.community_public_posts;
create view public.community_public_posts with (security_barrier) as
 select p.id,p.kind,p.project_id,p.author_name,p.title,p.body,p.visited_on,p.published_at,
  (select count(*) from public.community_likes l where l.post_id=p.id) as like_count,
  (select count(*) from public.community_comments c where c.post_id=p.id and c.status='approved') as comment_count,
  (select m.public_id from public.member_profiles m where m.user_id=p.user_id and m.show_profile) as author_public_id
 from public.community_posts p where p.status='approved';
drop view if exists public.community_public_members;
create view public.community_public_members with (security_barrier) as
 select m.public_id,coalesce(nullif(btrim(m.display_name),''),'이용자') as display_name,m.bio,m.created_at as joined_at,
  (select count(*) from public.community_posts p where p.user_id=m.user_id and p.status='approved') as post_count
 from public.member_profiles m where m.show_profile
  -- the same test as platform_account_restricted, inline: visitors read the view without executing that function
  and not exists(select 1 from public.member_status s where s.user_id=m.user_id and s.state<>'active' and (s.until is null or s.until>now()));
revoke all on public.community_public_posts,public.community_public_members from public,anon,authenticated;
grant select on public.community_public_posts,public.community_public_members to anon,authenticated,service_role;

-- ---- operator lists (admin + MFA) -------------------------------------------------------------------------------------
create or replace function public.platform_member_list(p_query text default null,p_limit integer default 50) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare q text:=nullif(btrim(coalesce(p_query,'')),''); out jsonb;
begin
 perform public.platform_require(array['admin']);
 select coalesce(jsonb_agg(x order by x->>'created_at' desc),'[]'::jsonb) into out from (
  select jsonb_build_object('user_id',u.id,'email',u.email,'created_at',u.created_at,'email_confirmed',u.email_confirmed_at is not null,
   'last_sign_in_at',u.last_sign_in_at,'state',coalesce(s.state,'active'),'state_reason',s.reason,'state_until',s.until,'role',a.role,
   'display_name',m.display_name,'posts',(select count(*) from public.community_posts p where p.user_id=u.id),
   'photos',(select count(*) from public.community_photos f where f.user_id=u.id),
   'submissions',(select count(*) from public.community_submissions c where c.user_id=u.id),
   'researcher',(select r.status from public.researcher_applications r where r.user_id=u.id order by r.created_at desc limit 1)) as x
  from auth.users u left join public.member_status s on s.user_id=u.id left join public.app_admins a on a.user_id=u.id
   left join public.member_profiles m on m.user_id=u.id
  where q is null or u.email ilike '%'||q||'%' or m.display_name ilike '%'||q||'%'
  order by u.created_at desc limit least(greatest(coalesce(p_limit,50),1),200)) t;
 perform public.platform_audit('member_list_viewed','member',null,jsonb_build_object('query',q,'rows',jsonb_array_length(out)));
 return out;
end $$;

create or replace function public.platform_research_grants(p_limit integer default 100) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
begin
 perform public.platform_require(array['admin']);
 return (select coalesce(jsonb_agg(jsonb_build_object('id',g.id,'email',u.email,'dataset_id',g.dataset_id,'application_id',g.application_id,
   'granted_at',g.granted_at,'expires_at',g.expires_at,'revoked_at',g.revoked_at,'revoke_reason',g.revoke_reason,
   'active',g.revoked_at is null and g.expires_at>now()) order by g.granted_at desc),'[]'::jsonb)
  from (select * from public.research_grants order by granted_at desc limit least(greatest(coalesce(p_limit,100),1),500)) g left join auth.users u on u.id=g.user_id);
end $$;

create or replace function public.platform_research_downloads(p_limit integer default 100) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
begin
 perform public.platform_require(array['admin']);
 return (select coalesce(jsonb_agg(jsonb_build_object('id',d.id,'email',u.email,'dataset_id',d.dataset_id,'version',d.version,'format',d.format,
   'ok',d.ok,'error',d.error,'requested_at',d.requested_at) order by d.requested_at desc),'[]'::jsonb)
  from (select * from public.research_downloads order by requested_at desc limit least(greatest(coalesce(p_limit,100),1),500)) d left join auth.users u on u.id=d.user_id);
end $$;

revoke all on function public.platform_member_list(text,integer),public.platform_research_grants(integer),public.platform_research_downloads(integer) from public,anon,authenticated;
grant execute on function public.platform_member_list(text,integer),public.platform_research_grants(integer),public.platform_research_downloads(integer) to authenticated,service_role;

commit;
